-- S2: repeat-heavy: 288 slots with 6 rows each (1,728) and 172 stray rows, 1,900 in the read range. 1900 rows in the table, 1900 in the read range.
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 287) INSERT INTO collector_runs (layer, started_at, finished_at, status, http_status, records, bytes, note) SELECT 'earthview', strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 600, 'unixepoch'), strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 600 + 15, 'unixepoch'), 'ok', 200, 0, 0, 'nothing newer: fixture frame' FROM n;
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 287), r(j) AS (SELECT 1 UNION ALL SELECT j + 1 FROM r WHERE j < 5) INSERT INTO collector_runs (layer, started_at, finished_at, status, http_status, records, bytes, note) SELECT 'earthview', strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 600, 'unixepoch'), strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + i * 600 + 15 + j, 'unixepoch'), 'ok', 200, 0, 0, 'nothing newer: fixture repeat' FROM n, r;
WITH RECURSIVE n(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM n WHERE i < 171) INSERT INTO collector_runs (layer, started_at, finished_at, status, http_status, records, bytes, note) SELECT 'earthview', strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + 300 + i * 600, 'unixepoch'), strftime('%Y-%m-%dT%H:%M:%fZ', 1795316400 + 300 + i * 600 + 15, 'unixepoch'), 'ok', 200, 0, 0, 'nothing newer: fixture stray' FROM n;
